{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Ketanserin, a 4-fluorobenzoyl piperidine closely related to the query, showed rapid and sustained brain uptake in baboon dynamic studies, directly demonstrating CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "[18F]Altanserin, another 4-fluorobenzoyl piperidine, showed sufficient brain uptake in rat micro-PET studies, supporting CNS penetration of the shared core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "BMP, a 4-fluorobenzoyl piperidine derivative, showed extremely high brain uptake (>14% ID/g) in mice, demonstrating strong BBB penetration for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "FK962, a low-molecular-weight fluorinated aryl amide with a basic amine, reached 160 nM in rat brain after 0.1 mg/kg and was labeled as good penetration, supporting transferable CNS access despite ionizable features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "JNJ-39220675, a related fluorophenyl CNS ligand, showed an average brain-to-plasma ratio of 3.4 after subcutaneous dosing in rats, confirming meaningful brain entry for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Spiperone, a butyrophenone containing the 4-fluorobenzoyl piperidine motif, entered mouse brain with Cmax ~70 ng/g after subcutaneous dosing, demonstrating CNS access for the family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4-fluorobenzoyl piperidine with a hydroxy-tetralin N-substituent. Multiple close analogues sharing the same fluorobenzoyl piperidine/butyrophenone core show robust brain uptake across species (baboon, rat, mouse, pig, monkey). Direct in vivo evidence outweighs the moderate ionization prior, so the molecule is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "Efflux transporter status was not directly measured for the query, though the analogue evidence suggests adequate net brain uptake.",
    "The basic piperidine and hydroxyl group may affect unbound brain concentration, but not overall CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

